INSERT INTO journey_entries (year, title, description, details, icon_name, highlight, sort_order) VALUES
(2000, 'Born in New York', 'Born Homer James Jigme Gere on February 6, 2000 in New York City.', 'Named after his paternal grandfather Homer George Gere. His middle name "Jigme" is Tibetan for "fearless" or "courageous," reflecting his father''s Buddhist faith.', 'user', NULL, 1),
(2018, 'Graduated Hackley School', 'Completed secondary education at Hackley School in Westchester, New York.', 'Attended the private Hackley School from September 2014 through graduation in June 2018.', 'graduation-cap', NULL, 2),
(2019, 'Brown University', 'Enrolled at Brown University to study Cognitive Neuroscience and Visual Arts.', 'Joined Brown University in Providence, Rhode Island, pursuing a Bachelor of Arts degree majoring in Cognitive Neuroscience and Visual Arts. Graduated in 2024.', 'graduation-cap', NULL, 3),
(2023, 'Early Film Work', 'Appeared in short film projects before transitioning to major television roles.', 'Built early experience through independent short film projects, including credits on IMDB for short films prior to his television debut.', 'clapperboard', NULL, 4),
(2026, 'Euphoria Season 3', 'Cast as Dylan Reid in HBO''s Euphoria third and final season.', 'Made his television debut portraying Dylan Reid in 4 episodes. The casting was announced by BBC News in October 2025; the season premiered in May 2026.', 'award', 'TV Debut', 5),
(2025, 'The Shards', 'Cast as Robert Mallory in Ryan Murphy and Bret Easton Ellis''s FX/Hulu series.', 'His first major leading role, starring alongside Igby Rigney, Kaia Gerber, Hayes Warner, Graham Campbell, Wes Bentley, and Evan Rachel Wood. Premiered August 5, 2026.', 'star', 'First Lead Role', 6),
(2026, 'White Lies', 'Cast in an Oliver Stone film.', 'Announced in June 2026, Gere was cast in the Oliver Stone film "White Lies." Details about the role and release date are forthcoming.', 'film', NULL, 7);

