INSERT INTO journal_articles (slug, title, excerpt, content, category, author, author_role, cover_image, published_date, reading_time, word_count, featured, trending, status, tags, seo_title, seo_description) VALUES
('the-shards-world-premiere-sva-theatre', 'The Shards Makes Its World Debut at SVA Theatre', 'Homer Gere leads the cast of FX''s The Shards at the world premiere in New York City.', 'On the evening of July 27, 2026, the cast and creative team of FX''s The Shards descended upon the SVA Theatre in Manhattan''s Chelsea neighborhood for the world premiere of the series. Homer Gere, who stars as Robert Mallory in what is his first leading role in a major television production, walked the red carpet alongside his co-stars Kaia Gerber, Igby Rigney, Graham Campbell, and Hayes Warner.', 'events', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-08-08', '12 min read', 1847, true, true, 'published', ARRAY['The Shards', 'Premiere', 'FX', 'Ryan Murphy', 'Robert Mallory']::text[], 'The Shards World Premiere at SVA Theatre — Homer Gere Leads FX Series', 'Full coverage of the world premiere of FXs The Shards at SVA Theatre in New York City.'),

('euphoria-season-3-hbo-premiere', 'Euphoria Season 3 Premieres on HBO', 'Homer Gere returns as Dylan Reid across four episodes of the new season.', 'HBO''s Euphoria Season 3 premiered on May 21, 2026, marking the return of one of the network''s most culturally significant series. Homer Gere reprises his role as Dylan Reid, appearing in four episodes of the ten-episode season.', 'productions', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-05-22', '11 min read', 1634, false, true, 'published', ARRAY['Euphoria', 'HBO', 'Season 3', 'Dylan Reid']::text[], 'Euphoria Season 3 — Homer Gere as Dylan Reid | HBO', 'Homer Gere returns as Dylan Reid in Euphoria Season 3 on HBO.'),

('oliver-stone-white-lies-film-announcement', 'Oliver Stone''s White Lies Confirms Homer Gere Alongside Douglas, Dafoe', 'Academy Award-winning director Oliver Stone assembles a formidable cast including Homer Gere.', 'In June 2026, it was announced that Homer Gere has been cast in Oliver Stone''s upcoming feature film White Lies, alongside Academy Award winners Michael Douglas, Willem Dafoe, and Ellen Barkin.', 'announcements', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-06-15', '10 min read', 1589, false, true, 'published', ARRAY['White Lies', 'Oliver Stone', 'Michael Douglas', 'Willem Dafoe']::text[], 'Oliver Stone''s White Lies — Homer Gere Cast Alongside Douglas & Dafoe', 'Homer Gere joins Oliver Stone''s White Lies alongside Michael Douglas, Willem Dafoe, and Ellen Barkin.'),

('british-vogue-who-is-homer-gere', 'Who Is Homer Gere? — British Vogue Explores the Next Chapter', 'British Vogue publishes a comprehensive profile on Homer Gere ahead of The Shards premiere.', 'In the weeks leading up to the premiere of The Shards, British Vogue published a comprehensive profile on Homer Gere under the headline "Who Is Homer Gere?" — a question that, at the time, many in the entertainment industry were beginning to ask with increasing urgency.', 'press', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-07-20', '9 min read', 1420, false, false, 'published', ARRAY['British Vogue', 'Profile', 'The Shards']::text[], '"Who Is Homer Gere?" — British Vogue Profile', 'British Vogue publishes a comprehensive profile on Homer Gere.'),

('the-shards-behind-the-scenes-65mm-film', 'Behind the Lens: How The Shards Was Shot on 65mm Film', 'An inside look at the cinematography choices behind FX''s most visually ambitious series.', 'The decision to shoot The Shards on 65mm Kodak VERITA 200D film stock was driven by the desire to capture an immersive visual quality that digital formats cannot replicate. Cinematographer Marcell Rév brought his distinctive visual approach to the series.', 'behind-the-scenes', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-08-12', '8 min read', 1200, false, false, 'published', ARRAY['The Shards', 'Cinematography', '65mm', 'Marcell Rév', 'Behind the Scenes']::text[], 'Behind the Lens: How The Shards Was Shot on 65mm Film', 'An inside look at the cinematography behind FX The Shards.'),

('the-shards-launch-party-moonlight-rollerway', 'The Shards Cast Gathers at Moonlight Rollerway', 'The official launch party for FX''s The Shards brings the cast together for a night of celebration.', 'Following the world premiere at SVA Theatre, the cast and crew of The Shards gathered at Moonlight Rollerway in Glendale, California for the official series launch party.', 'events', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-08-06', '6 min read', 900, false, false, 'published', ARRAY['The Shards', 'Launch Party', 'Moonlight Rollerway']::text[], 'The Shards Launch Party at Moonlight Rollerway', 'The official launch party for FX The Shards.'),

('brown-university-cognitive-neuroscience-visual-arts', 'From Brown University to the Screen', 'How Homer Gere''s education in cognitive neuroscience shaped his approach to acting.', 'Studying Cognitive Neuroscience and Visual Arts at Brown University gave Homer Gere a unique lens on performance. Understanding how the brain processes emotion and perception has directly influenced how he approaches character work.', 'personal-stories', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-04-10', '7 min read', 1100, false, false, 'published', ARRAY['Brown University', 'Education', 'Cognitive Neuroscience']::text[], 'From Brown University to the Screen — Homer Gere', 'How Homer Gere education shaped his approach to acting.'),

('bbc-news-highlights-homer-gere', 'BBC News Highlights Homer Gere as Emerging Talent', 'BBC News features Homer Gere in a roundup of emerging talent to watch in 2026.', 'BBC News featured Homer Gere in a roundup of emerging talent to watch in 2026, highlighting his background, education, and rapidly growing career in the entertainment industry.', 'press', 'Official Editorial', 'HomerGere.com Editorial Team', NULL, '2026-03-15', '5 min read', 800, false, false, 'published', ARRAY['BBC News', 'Emerging Talent']::text[], 'BBC News Highlights Homer Gere as Emerging Talent', 'BBC News features Homer Gere in emerging talent roundup.');

